# frozen_string_literal: true
# New Phase 5/6/8 landing pages. Public copy is rendered by Jekyll; personal
# inputs are handled only in the visitor's browser by phase-5-6-8.js.
module Phase568Pages
 extend self
 def page(path,title,description,body,module_name=nil)
  Pages.page(path,title,description,body,true,nil,false,module_name)
 end
 def links(items)
  '<nav class="resource-grid" aria-label="Susiję puslapiai">'+items.map { |url,label,copy|Pages.resource_card(url,label,copy) }.join+'</nav>'
 end
 def run
  shift=Pages.intro('Pamainų grafiko planuoklis','Sukurkite pasikartojantį pamainų ciklą, peržiūrėkite darbo ir poilsio laikotarpius bei išsaugokite grafiką šiame įrenginyje.')+<<~HTML
   <section class="panel"><h2>Jūsų ciklas lieka šiame įrenginyje</h2><p>Pasirinkite ciklo pradžią, laikotarpį ir kiekvienos pamainos laiką. Įrankis parodo kalendorines pamainas, per vidurnaktį dirbtas valandas, neapmokamas pertraukas ir poilsio tarpus. Skaičiavimas skirtas planuoti, nepatvirtina darbo grafiko teisėtumo ar darbo užmokesčio.</p><p>Visi asmeniniai įrašai saugomi lokaliai. Nereikia paskyros, vardo, darbdavio ar darbovietės adreso. Eksportuokite atsarginę JSON kopiją prieš keisdami įrenginį.</p></section>
   <form id="shift-planner" class="panel phase-tool" novalidate>
    <div class="form-row"><label>Ciklo pradžios data<input id="shift-anchor" type="date" required></label><label>Rodomas laikotarpis nuo<input id="shift-from" type="date" required></label><label>Iki (imtinai)<input id="shift-to" type="date" required></label></div>
    <label>Grafiko pradžios šablonas<select id="shift-preset"><option value="day-rest">2 dieninės, 2 poilsio</option><option value="day-night">2 dieninės, 2 naktinės, 4 poilsio</option><option value="custom">Savo ciklas</option></select></label><label>Pasikartojantis ciklas <span class="muted">Žymos atskirtos kableliais: D,D,P,P arba D,D,N,N,P,P,P,P. P reiškia poilsio dieną.</span><input id="shift-cycle" maxlength="160" value="D,D,P,P" autocomplete="off"></label>
    <label>Pamainų aprašai (JSON) <span class="muted">Kiekvienai naudojamai žymai aprašykite pavadinimą, pradžią, pabaigą, neapmokamos pertraukos minutes ir spalvą. Pridėkite savo žymas, pvz., R – vakarinė.</span><textarea id="shift-definitions" rows="5" spellcheck="false">{"D":{"name":"Dieninė","start":"07:00","end":"19:00","break":0,"color":"#006a44"},"N":{"name":"Naktinė","start":"19:00","end":"07:00","break":0,"color":"#315bd6"}}</textarea></label>
    <fieldset><legend>Vasaros laiko pasikartojanti vietinė valanda</legend><p>Pavasarį kai kurios vietinės valandos neegzistuoja. Rudenį dalis valandų pasikartoja. Neegzistuojančio laiko atveju įrankis sustabdo eksportą; pasikartojančiam laikui pasirinkite ankstesnį arba vėlesnį momentą.</p><label>Pasikartojančios valandos pasirinkimas<select id="shift-fold"><option value="ask">Sustabdyti ir parodyti pasirinkimą</option><option value="earlier">Ankstesnis momentas</option><option value="later">Vėlesnis momentas</option></select></label></fieldset>
    <div class="form-row"><label>Suvestinės grupavimas<select id="shift-view"><option value="week">Pagal savaites</option><option value="month">Pagal mėnesius</option><option value="year">Pagal metus</option><option value="list">Nerodyti grupuotos lentelės</option></select></label><label>Grafiko vaizdas<select id="shift-display"><option value="list">Išsamus sąrašas</option><option value="month">Mėnesio kalendorius</option><option value="week">Savaitės laiko juosta</option><option value="year">Metų apžvalga</option></select></label><label>Savaitės dienų filtras<select id="shift-week-filter"><option value="all">Visos dienos</option><option value="five">5 dienos · pirm.–penkt.</option><option value="six">6 dienos · pirm.–šešt.</option><option value="custom">Pasirinkti dienas</option></select></label></div><fieldset id="shift-custom-days" class="weekday-filter" hidden><legend>Rodyti šias pamainų pradžios dienas</legend><div id="shift-custom-days-list" class="weekday-options"></div></fieldset><p class="source-note">Savaitės dienų filtras veikia tik pasirinktą vaizdą. Suvestinės ir atsisiunčiamas ICS apima visą sudarytą grafiką.</p><div class="form-actions"><button class="primary" type="submit">Apskaičiuoti grafiką</button><button type="button" id="shift-json-export">Atsisiųsti JSON kopiją</button><label class="button">Atkurti JSON kopiją<input id="shift-json-import" type="file" accept="application/json,.json" hidden></label><button type="button" id="shift-ics">Atsisiųsti ICS</button><button type="button" id="shift-print">Spausdinti grafiką</button></div>
    <p id="shift-message" class="result" role="status" aria-live="polite">Pasirinkite ne ilgesnį kaip 370 dienų laikotarpį.</p>
   </form>
   <section class="panel"><h2>Grafiko suvestinė</h2><div id="shift-summary" class="calculator-results" aria-live="polite"><p>Įveskite ciklą ir apskaičiuokite peržiūrą.</p></div><div id="shift-visualization" class="shift-visualization" aria-live="polite"></div><div class="table-scroll" tabindex="0" role="region" aria-label="Pamainų laikotarpio suvestinė"><table class="data-table"><thead><tr><th>Laikotarpis</th><th>Pamainos</th><th>Dieninės</th><th>Naktinės</th><th>Įvertintos valandos</th><th>Įstatymo švenčių datos</th></tr></thead><tbody id="shift-periods"></tbody></table></div><div id="shift-list-region" class="table-scroll" tabindex="0" role="region" aria-label="Išsamus pamainų sąrašas"><table class="data-table"><thead><tr><th>Data</th><th>Ciklo žyma</th><th>Pamainos laikas</th><th>Praėjęs laikas</th><th>Įvertintos darbo valandos</th><th>Poilsis iki kitos</th></tr></thead><tbody id="shift-rows"></tbody></table></div><p id="shift-warning" class="source-note">Planavimo priminimai nėra teisinė išvada. Nakties, viršvalandžių, suminės apskaitos, sutarčių, profesijos ir taikomų išimčių įrankis netikrina.</p></section>
   <h2>Kaip naudoti pasikartojantį grafiką</h2><p>Įrašykite ciklą, pavyzdžiui, <strong>D,D,P,P</strong> arba <strong>D,D,N,N,P,P,P,P</strong>. Pirma ciklo žyma taikoma pradžios dienai, o paskesnės kartojamos iš eilės. Jei pasirinktame cikle nėra N žymos, nakties laikai nebus naudojami. Per naktį besitęsianti pamaina priskiriama jos pradžios kalendorinei dienai.</p><p>Įvestis gali būti netaisyklinga konkrečiai darbo vietai. <a href="https://vdi.lrv.lt/lt/naujienos/vdi-informuoja-ka-apie-poilsio-laika-butina-zinoti-kiekvienam-darbuotojui/?lang=en" rel="noopener">VDI bendroje informacijoje apie poilsį</a> nurodomi 11 valandų nepertraukiamo paros poilsio, 35 valandų savaitės poilsio ir ilgesnei nei 12 val. pamainai – 24 val. poilsio atskaitos dydžiai; išimtys ir režimai skiriasi. Šis įrankis gali pažymėti trumpą tarpą kaip peržiūros priminimą, bet nesprendžia teisėtumo.</p>
   #{links([['darbo-dienos/2027/','Darbo dienų kalendorius','Įstatymo šventės ir standartinės savaitės skaičiavimo metodika.'],['darbo-grafiko-sablonai/','Darbo grafiko šablonai','Atsisiunčiami tušti ciklo lapai.'],['irankiai/','Visi įrankiai','Kalendoriaus ir darbo laiko skaičiuoklės.']])}
  HTML
  page('pamainu-grafikas','Pamainų grafiko planuoklis – ciklai ir darbo laikas',
    'Sukurkite pamainų ciklą Lietuvoje: dieninės ir naktinės pamainos, poilsio dienos, pertrauka, vasaros laiko patikra, darbo valandų suvestinė ir ICS eksportas.',shift,'shift')

  school=Pages.intro('Pamokų tvarkaraštis ir namų darbų planuoklis','Redaguojamas savaitės tvarkaraštis, užduotys ir atsiskaitymų datos. Jūsų informacija neiškeliauja iš naršyklės.')+<<~HTML
   <section class="panel"><h2>Tvarkaraštis be privalomų asmens duomenų</h2><p>Pridėkite tiek pamokų, kiek reikia, pasirinkite 5 arba 6 savaitės dienas ir kiekvienai pamokai nustatykite atskirą laiką. Įrankis netaiko universalaus pamokos ilgio ir nenumano nepatvirtintų mokslo metų datų. Vardas, mokinio kodas, klasės ar mokyklos pavadinimas nereikalingi.</p><p>Tvarkaraštis, mokytojo trumpinys ir namų darbų tekstas saugomi tik šioje naršyklėje. Atsisiųskite JSON atsarginę kopiją, atsispausdinkite arba ištrinkite vietinius duomenis.</p></section>
   <form id="school-planner" class="panel phase-tool" novalidate><div class="form-row"><label>Rodomos savaitės dienos<select id="school-days"><option value="5">Pirmadienis–penktadienis</option><option value="6">Pirmadienis–šeštadienis</option></select></label><label>Tvarkaraščio pavadinimas (nebūtinas)<input id="school-title" maxlength="60"></label><label>Šablonas<select id="school-template"><option value="regular">Įprastas</option><option value="large">Didelis šriftas</option><option value="compact">Kompaktiškas</option><option value="mono">Nespalvotas</option></select></label></div><div class="form-actions"><button type="button" id="lesson-add">Pridėti pamoką</button><button type="button" id="school-duplicate-week">Kopijuoti pirmadienį į tuščias vietas</button><button type="button" id="school-clear-week">Išvalyti savaitę</button><button type="button" id="school-undo" disabled>Anuliuoti</button><button type="button" id="school-print">Spausdinti tvarkaraštį</button><button type="button" id="school-json-export">Atsisiųsti JSON kopiją</button><label class="button">Atkurti JSON kopiją<input id="school-json-import" type="file" accept="application/json,.json" hidden></label><button type="button" id="school-reset">Ištrinti šio įrenginio duomenis</button></div><p id="school-message" class="result" role="status" aria-live="polite"></p></form>
   <section class="panel"><h2>Savaitės pamokos</h2><div class="table-scroll" tabindex="0" role="region" aria-label="Redaguojamas pamokų tvarkaraštis"><table class="data-table school-table"><thead><tr><th>Diena</th><th>Nr.</th><th>Pradžia</th><th>Pabaiga</th><th>Dalykas</th><th>Kabinetas</th><th>Mokytojo trumpinys</th><th></th></tr></thead><tbody id="school-lessons"></tbody></table></div></section>
   <section class="panel"><h2>Namų darbai ir artėjantys atsiskaitymai</h2><form id="homework-form" class="form-row"><label>Dalykas<input id="homework-subject" maxlength="50" required></label><label>Užduotis<input id="homework-task" maxlength="180" required></label><label>Terminas<input id="homework-due" type="date" required></label><label>Prioritetas<select id="homework-priority"><option value="normal">Įprastas</option><option value="high">Svarbus</option></select></label><button type="submit">Pridėti užduotį</button></form><ul id="homework-list" class="phase-list"></ul></section>
   <p class="source-note">Mokinio įrašai yra privatūs ir įrenginio vietinėje saugykloje. Svetainė jų nesiunčia į serverį. Išvalius naršyklės duomenis jie gali būti prarasti, todėl atsarginę JSON kopiją saugokite patys. ICS su realiomis pamokų datomis kuriamas tik turint tikslias mokslo metų ribas ir išimtis; šiame pasikartojančiame savaitės šablone datų neišgalvojame.</p>
   <h2>Mokyklos savaitės planavimas Lietuvoje</h2><p>Šis įrankis yra asmeninis tvarkaraščio ir užduočių planuoklis, o ne mokyklos administravimo ar valstybės sertifikuota sistema. Tvarkaraštyje galima turėti nevienodos trukmės pamokas ir skirtingas dienos pertraukas. <a href="https://e-tar.lt/portal/lt/legalAct/TAR.2581A7005CA7/DceqKtHoXM" rel="noopener">HN 21:2017 galiojanti redakcija</a> nustato ugdymo proceso higienos reikalavimus ir numato sąlygas, kurioms esant mokykla gali taikyti pakeitimus; asmeninis šablonas jų atitikties nepatvirtina. 2027–2028 mokslo metų atostogų datos čia nėra iš anksto įrašytos, kol jų nepatvirtina kompetentinga institucija.</p>
   #{links([['pamoku-tvarkarascio-sablonai/','Pamokų tvarkaraščio šablonai','Tušti spausdinami mokyklos planai.'],['mokiniu-atostogos/','Mokinių atostogos','Skelbiamos ir patikrintos 2026–2027 mokslo metų datos.'],['tuscias-kalendorius/','Tušti planuokliai','Nedatuoti savaitės ir mėnesio lapai.']])}
  HTML
  page('pamoku-tvarkarastis','Pamokų tvarkaraštis ir namų darbų planuoklis',
    'Sukurkite savaitinį pamokų tvarkaraštį ir namų darbų sąrašą: keičiamos pamokų trukmės, 5 arba 6 dienos, vietinis saugojimas, JSON kopija ir spausdinimas.',school,'school')

  sun=<<~HTML
   <div class="page-heading sun-page-heading"><div><p class="sun-eyebrow"><span aria-hidden="true">✦</span> Saulės ritmas virš Lietuvos</p><h1>Saulėtekis, saulėlydis ir Saulės kelias</h1><p class="page-intro">Pasirinkite miestą ir datą: pamatykite, kada pateka ir leidžiasi Saulė, kiek trunka šviesus paros metas ir kaip ji keliauja dangumi.</p></div></div>
   <section class="sun-controls" aria-label="Saulės laikų pasirinkimai"><div class="sun-controls__copy"><span class="sun-controls__icon" aria-hidden="true"><svg viewBox="0 0 48 48" focusable="false"><circle cx="24" cy="24" r="9"/><path d="M24 4v6m0 28v6M4 24h6m28 0h6M9.9 9.9l4.2 4.2m19.8 19.8 4.2 4.2m0-28.2-4.2 4.2m-19.8 19.8-4.2 4.2"/></svg></span><div><strong>Pasirinkite savo dieną</strong><p>Laikai pateikiami Lietuvos laiku · Europe/Vilnius</p></div></div><div class="sun-controls__fields"><label for="sun-city">Miestas<select id="sun-city"><option value="vilnius">Vilnius</option><option value="kaunas">Kaunas</option><option value="klaipeda">Klaipėda</option><option value="siauliai">Šiauliai</option><option value="panevezys">Panevėžys</option></select></label><label for="sun-date">Data<input id="sun-date" type="date" min="2000-01-01" max="2100-12-31"></label><button id="sun-today" type="button" class="sun-today"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><rect x="3.5" y="5" width="17" height="16" rx="2.5"/><path d="M7.5 3v4M16.5 3v4M4 9h16M8 13h3m-3 4h3m3-4h2"/></svg> Šiandien</button></div></section>
   <section id="sun-tool" class="sun-tool" aria-labelledby="sun-experience-title">
    <section class="sun-scene-card" aria-labelledby="sun-experience-title"><div class="sun-scene-card__top"><div><p class="sun-eyebrow">Interaktyvi simuliacija</p><h2 id="sun-experience-title">Saulės kelias danguje</h2><p id="sun-scene-caption">Vilkite laiko žymeklį ir stebėkite Saulės padėtį.</p></div><div class="sun-clock-badge"><span class="sun-clock-badge__dot" aria-hidden="true"></span><span id="sun-sim-time">--:--</span><small id="sun-sim-phase">Dienos šviesa</small></div></div><div id="sun-scene" class="sun-scene" role="img" aria-label="Pasirinktos dienos apskaičiuotas Saulės kelias danguje"><p class="sun-scene__fallback">Pasirinkite miestą ir datą, kad būtų apskaičiuotas Saulės kelias.</p></div><div class="sun-scene-legend" aria-label="Diagramos paaiškinimas"><span><i class="sun-legend-dot sun-legend-dot--rise"></i> Saulėtekis</span><span><i class="sun-legend-dot sun-legend-dot--noon"></i> Saulės vidurdienis</span><span><i class="sun-legend-dot sun-legend-dot--set"></i> Saulėlydis</span><span class="sun-legend-note">Kreivė apskaičiuota pagal miesto koordinates ir datą</span></div><div class="sun-scrubber"><div class="sun-scrubber__head"><label for="sun-scrubber">Judinkite laiką nuo aušros iki vakaro</label><output id="sun-sim-output" for="sun-scrubber" aria-live="off">--:--</output></div><input id="sun-scrubber" type="range" min="0" max="1000" step="1" value="0" aria-label="Saulės padėtis nuo civilinės aušros iki vakaro"><div class="sun-moments" aria-label="Pasirinkti Saulės įvykio laiką"><button type="button" data-sun-moment="civilStart"><span>Aušra</span> <time id="sun-civil-start">--:--</time></button><button type="button" data-sun-moment="sunrise"><span>Saulėtekis</span> <time id="sun-rise-time">--:--</time></button><button type="button" data-sun-moment="noon"><span>Vidurdienis</span> <time id="sun-noon-time">--:--</time></button><button type="button" data-sun-moment="sunset"><span>Saulėlydis</span> <time id="sun-set-time">--:--</time></button><button type="button" data-sun-moment="civilEnd"><span>Vakaras</span> <time id="sun-civil-end">--:--</time></button></div><div class="sun-scrubber__actions"><p id="sun-sim-detail">Saulės aukštis ir kryptis bus parodyti pasirinkus datą.</p><button id="sun-play" type="button" aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M8 5.5v13l10-6.5z"/></svg><span>Paleisti animaciją</span></button></div></div></section>
    <p id="sun-summary" class="visually-hidden" aria-live="polite">Apskaičiuojami pasirinktos dienos Saulės laikai.</p>
    <section class="sun-metrics" aria-label="Pasirinktos dienos Saulės laikai"><article class="sun-metric sun-metric--rise"><span class="sun-metric__icon" aria-hidden="true"><svg viewBox="0 0 48 48" focusable="false"><path d="M8 31h32M13 31a11 11 0 0 1 22 0M24 5v7m-15 5 5 5m25-5-5 5M5 26h7m24 0h7"/><path d="m18 36 6-6 6 6"/></svg></span><div><span class="sun-metric__label">Saulėtekis</span><strong id="sunrise-time">--:--</strong><small id="sunrise-date">Saulės disko viršutinis kraštas ties horizontu</small></div></article><article class="sun-metric sun-metric--length"><span class="sun-metric__icon" aria-hidden="true"><svg viewBox="0 0 48 48" focusable="false"><circle cx="24" cy="24" r="9"/><path d="M24 4v6m0 28v6M4 24h6m28 0h6M9.9 9.9l4.2 4.2m19.8 19.8 4.2 4.2m0-28.2-4.2 4.2m-19.8 19.8-4.2 4.2"/></svg></span><div><span class="sun-metric__label">Dienos šviesa</span><strong id="sun-day-length">-- val. -- min.</strong><small id="sun-day-change">Šviesaus paros meto trukmė</small></div></article><article class="sun-metric sun-metric--noon"><span class="sun-metric__icon" aria-hidden="true"><svg viewBox="0 0 48 48" focusable="false"><circle cx="24" cy="24" r="8"/><path d="M24 4v5m0 30v5M4 24h5m30 0h5M10 10l4 4m20 20 4 4m0-28-4 4m-20 20-4 4M15 24h18"/></svg></span><div><span class="sun-metric__label">Saulės vidurdienis</span><strong id="sun-noon">--:--</strong><small>Aukščiausia Saulės padėtis tą dieną</small></div></article><article class="sun-metric sun-metric--set"><span class="sun-metric__icon" aria-hidden="true"><svg viewBox="0 0 48 48" focusable="false"><path d="M8 31h32M13 31a11 11 0 0 1 22 0M24 5v7m-15 5 5 5m25-5-5 5M5 26h7m24 0h7"/><path d="m18 26 6 6 6-6"/></svg></span><div><span class="sun-metric__label">Saulėlydis</span><strong id="sunset-time">--:--</strong><small id="sunset-date">Saulės disko viršutinis kraštas ties horizontu</small></div></article></section>
    <section class="sun-delta" aria-label="Dienos šviesos pokytis"><span class="sun-delta__icon" aria-hidden="true">↗</span><p id="sun-delta-copy">Pasirinkite datą, kad palygintumėte dienos ilgį su gretimomis dienomis.</p></section>
    <section class="sun-analysis panel" aria-labelledby="sun-analysis-title"><div class="sun-section-heading"><div><p class="sun-eyebrow">Dienos šviesos kalendorius</p><h2 id="sun-analysis-title">Kaip keičiasi šviesus paros metas?</h2><p id="sun-chart-caption">Pasirinkto mėnesio dienos šviesos trukmė.</p></div><span class="sun-section-heading__symbol" aria-hidden="true">☼</span></div><div id="sun-chart" class="sun-chart sun-chart--month" role="img" aria-label="Pasirinkto mėnesio dienos šviesos trukmės diagrama"></div><details class="sun-data-details"><summary>Atverti mėnesio Saulės laikų lentelę</summary><div class="table-scroll" tabindex="0" role="region" aria-label="Mėnesio Saulės laikų lentelė"><table class="data-table"><caption id="sun-table-caption">Pasirinkto mėnesio Saulės laikai</caption><thead><tr><th scope="col">Data</th><th scope="col">Saulėtekis</th><th scope="col">Vidurdienis</th><th scope="col">Saulėlydis</th><th scope="col">Dienos šviesa</th><th scope="col">Civilinė prieblanda</th></tr></thead><tbody id="sun-rows"></tbody></table></div></details></section>
    <section class="sun-analysis sun-analysis--year panel" aria-labelledby="sun-year-title"><div class="sun-section-heading"><div><p class="sun-eyebrow">Metų perspektyva</p><h2 id="sun-year-title">Saulės šviesa per visus metus</h2><p id="sun-year-chart-caption">Metų kreivėje matyti sezonų kaita ir mėnesio ribos.</p></div><span class="sun-section-heading__symbol sun-section-heading__symbol--year" aria-hidden="true">◒</span></div><div id="sun-year-chart" class="sun-chart sun-chart--year" role="img" aria-label="Metų dienos šviesos trukmės diagrama"></div><div class="table-scroll" tabindex="0" role="region" aria-label="Metų dienos šviesos mėnesinė suvestinė"><table class="data-table"><caption id="sun-year-caption">Dienos šviesos trukmė pagal mėnesius</caption><thead><tr><th scope="col">Mėnuo</th><th scope="col">Vidurkis per dieną</th><th scope="col">Trumpiausia diena</th><th scope="col">Ilgiausia diena</th></tr></thead><tbody id="sun-year-rows"></tbody></table></div></section>
    <section class="sun-method panel" aria-labelledby="sun-method-title"><div class="sun-section-heading"><div><p class="sun-eyebrow">Metodika ir šaltiniai</p><h2 id="sun-method-title">Kaip apskaičiuojami saulėtekio ir saulėlydžio laikai?</h2><p>Aiškiai nurodome, ką reiškia skaičiavimas ir kas gali pakeisti stebimą laiką.</p></div><span class="sun-section-heading__symbol sun-section-heading__symbol--method" aria-hidden="true">⌖</span></div><div class="sun-method__grid"><article><h3>Astronominis skaičiavimas</h3><p>Skaičiuojant naudojamos USNO aprašytos apytikslės Saulės koordinatės: ekliptinė ilguma, rektascensija ir deklinacija. Saulės kelias atnaujinamas pagal pasirinktą UTC momentą, o saulėtekis ir saulėlydis iteruojami iki įprastinės 90,833° zenito ribos. Ji atitinka Saulės disko viršutinio krašto pasirodymą ties lygiu horizontu, esant vidutinei refrakcijai. Skaičiavimą palyginome su USNO API 20 atvejų penkiuose miestuose ir keturiomis skirtingo sezono datomis; visuose šiame patikrinime skirtumas neviršijo vienos UTC minutės.</p></article><article><h3>Ką rodo simuliacija?</h3><p>Saulės disko vieta ir kryptis diagramoje apskaičiuojamos pagal pasirinktą datą ir miesto koordinates. Ji padeda suprasti dienos ritmą, tačiau nėra konkrečios gatvės, oro ar horizonto fotografija.</p></article><article><h3>Kodėl stebimas laikas gali skirtis?</h3><p>Rezultatai paremti apytikslėmis miesto centro koordinatėmis ir jūros lygio horizontu. Pastatai, medžiai, vietovės aukštis, debesys, slėgis, temperatūra ir kitos atmosferos sąlygos gali pakeisti tai, ką matote realybėje. Dėl refrakcijos saulėtekio ir saulėlydžio laiko negalima garantuoti iki sekundės.</p></article><article><h3>Civilinė prieblanda</h3><p>Aušros pradžia ir vakaro pabaiga skaičiuojamos, kai geometrinis Saulės centras yra 6° žemiau horizonto. Prieblandos šviesumas priklauso ir nuo debesuotumo bei vietos aplinkos.</p></article></div><p class="sun-method__sources">Šaltiniai: <a href="https://aa.usno.navy.mil/faq/sun_approx" rel="noopener noreferrer">USNO apytikslių Saulės koordinačių metodas</a>, <a href="https://aa.usno.navy.mil/faq/alt_az" rel="noopener noreferrer">USNO aukščio ir azimuto skaičiavimas</a>, <a href="https://aa.usno.navy.mil/faq/RST_defs" rel="noopener noreferrer">patekėjimo, nusileidimo ir prieblandos apibrėžimai</a>, <a href="https://aa.usno.navy.mil/faq/rs_algor" rel="noopener noreferrer">USNO algoritmų apžvalga</a>, <a href="https://aa.usno.navy.mil/data/api" rel="noopener noreferrer">USNO API dokumentacija</a>. Miestų koordinatės iš <a href="https://www.geonames.org/export/" rel="noopener noreferrer">GeoNames</a> (CC BY; apytiksliai miesto centro taškai).</p></section>
   </section>
   #{links([['astronominis-kalendorius/','Astronominis kalendorius','Lygiadieniai, saulėgrįžos ir dangaus reiškiniai.'],['menulio-fazes/','Mėnulio fazės','Jaunatis, ketvirčiai ir pilnatis Lietuvos laiku.'],['2027/','2027 metų kalendorius','Šventės ir spausdinami metų failai.']])}
  HTML
  page('saule','Saulėtekis, saulėlydis ir Saulės kelias Lietuvoje',
    'Patikrinkite saulėtekio, saulėlydžio ir civilinės prieblandos laiką penkiuose Lietuvos miestuose. Interaktyvi Saulės kelio simuliacija ir dienos ilgumo diagramos.',sun,'sun')

  moon=Pages.intro('Mėnulio fazės','Jaunaties, pirmojo ketvirčio, pilnaties ir paskutinio ketvirčio momentai paversti Lietuvos vietos laiku.')+<<~HTML
   <section class="panel"><h2>Tikslūs fazių momentai ir apytikslis apšviestumas</h2><p>Pagrindinė fazė yra visos Žemės mastu bendras momentas; ji nepriklauso nuo pasirinkto Lietuvos miesto. Laikai šaltinyje pateikti UTC minutės tikslumu ir konvertuojami į Europe/Vilnius vietos laiką, todėl fazės data Lietuvoje gali skirtis nuo UTC datos. Apšviesto Mėnulio dalis tarp pirminių fazių yra apytikslis geometrinis įvertis, o ne tiksli efemeridė.</p><p>Šiame puslapyje nėra astrologinių prognozių, sveikatos ar žemdirbystės teiginių. Mėnulio patekėjimo ir nusileidimo valandų nerodome, nes jų vietinė reikšmė turi būti skaičiuojama atskirai kiekvienam stebėtojui.</p></section>
   <section id="moon-tool" class="panel phase-tool"><div class="form-row"><label>Metai<select id="moon-year"><option>2027</option><option>2028</option><option>2029</option></select></label><label>Mėnuo<select id="moon-month"><option value="1">Sausis</option><option value="2">Vasaris</option><option value="3">Kovas</option><option value="4">Balandis</option><option value="5">Gegužė</option><option value="6">Birželis</option><option value="7">Liepa</option><option value="8">Rugpjūtis</option><option value="9">Rugsėjis</option><option value="10">Spalis</option><option value="11">Lapkritis</option><option value="12">Gruodis</option></select></label><button id="moon-show" type="button">Rodyti fazes</button></div><p id="moon-next" class="result" aria-live="polite"></p><div class="table-scroll"><table class="data-table"><caption id="moon-caption">Pagrindinės Mėnulio fazės pasirinktam mėnesiui</caption><thead><tr><th>Fazė</th><th>Momentas Lietuvoje</th><th>Apšviesto disko įvertis</th></tr></thead><tbody id="moon-rows"></tbody></table></div><div id="moon-calendar" class="moon-calendar" aria-label="Mėnesio fazių kalendorius"></div></section>
   <p class="source-note">Fazių UTC laikai apskaičiuoti <a href="https://aa.usno.navy.mil/data/api" rel="noopener">U.S. Naval Observatory Astronomical Applications Department API</a> (v4.0.1) paslauga. USNO oficialiame <a href="https://aa.usno.navy.mil/about/PrivacyNotice" rel="noopener">informacijos naudojimo pranešime</a> nurodo, kad svetainės informacija gali būti platinama ir kopijuojama, jei atskirai nenurodyta kitaip, ir prašo tinkamai nurodyti šaltinį. Šiame projekte pateikiama tokia atribucija; pranešimas nėra atskira SPDX ar Creative Commons licencija.</p>
   #{links([['menulio-kalendorius/2027/','2027 metų Mėnulio kalendorius','Visos mėnesio fazės pagal vietos laiką.'],['menulio-kalendorius/2028/','2028 metų Mėnulio kalendorius','Keliamųjų metų datos ir vasario 29-osios patikra.'],['menulio-kalendorius/2029/','2029 metų Mėnulio kalendorius','Visų 2029 metų jaunatis, ketvirčiai ir pilnatis.']])}
  HTML
  page('menulio-fazes','Mėnulio fazės 2027–2029 – jaunatis ir pilnatis',
    'Jaunaties, ketvirčio ir pilnaties momentai 2027–2029 m. Lietuvos laiku. Mėnulio disko apšviestumas nurodomas kaip apytikslis.',moon,'moon')
  (2027..2029).each do |year|
   body=Pages.intro("#{year} metų Mėnulio kalendorius","#{year} metų jaunaties, ketvirčių ir pilnaties momentai. UTC minutės tikslumas perskaičiuojamas į Lietuvos laiko juostą; apšviestumas tarp įvykių apytikslis.")+"<section id=\"moon-year-tool\" data-year=\"#{year}\" class=\"panel\"><h2>Fazės pagal mėnesius</h2><p>Mėnesio fazės pateiktos tikrais pirminių įvykių momentais, o ne kartojamu 29,5 dienos šablonu. Laikai nurodomi Europe/Vilnius laiku.</p><div id=\"moon-year-grid\" class=\"moon-year-grid\"></div><p><a href=\"/menulio-fazes/\">Pasirinkti kitus metus ar mėnesį</a> · <a href=\"/astronominis-kalendorius/\">Astronominis kalendorius</a></p></section><p class=\"source-note\">Šaltinis: <a href=\"https://aa.usno.navy.mil/data/MoonPhases\" rel=\"noopener\">USNO fazių lentelės</a>; laiko ir teisių apribojimai paaiškinti pagrindiniame fazių puslapyje.</p>"
   page("menulio-kalendorius/#{year}","#{year} metų Mėnulio kalendorius Lietuvoje","#{year} metų Mėnulio fazių kalendorius: tikslios jaunaties, ketvirčių ir pilnaties akimirkos Lietuvos laiku; vasaros laikas ir metų sandūra.",body,'moon')
  end

  seasons=Pages.intro('Astronominis kalendorius','Lietuvos laiku apskaičiuojami saulėgrįžų, lygiadienių, saulėtekio, dienos ilgumo ir Mėnulio fazių orientyrai.')+<<~HTML
   <section class="panel"><h2>Metų laikų astronominiai momentai</h2><p>Saulėgrįža ir lygiadienis yra konkretūs momentai, o ne fiksuotos vietos kalendoriaus dienos. Šioje lentelėje laikas konvertuojamas iš UTC į Europe/Vilnius. UTC minutės paimtos iš <a href="https://aa.usno.navy.mil/data/Earth_Seasons" rel="noopener">USNO sezonų skaičiuoklės</a>.</p><div class="table-scroll"><table class="data-table"><thead><tr><th>Metai</th><th>Pavasario lygiadienis</th><th>Vasaros saulėgrįža</th><th>Rudens lygiadienis</th><th>Žiemos saulėgrįža</th></tr></thead><tbody id="season-rows"></tbody></table></div><p>USNO oficialiame <a href="https://aa.usno.navy.mil/about/PrivacyNotice" rel="noopener">informacijos naudojimo pranešime</a> leidžiama platinti ir kopijuoti svetainės informaciją, jei atskirai nenurodyta kitaip, prašant tinkamos atribucijos. Saulėtekio ir dienos šviesos skaičiuoklė veikia penkiems Lietuvos miestams. Fazės pateikiamos visuotiniais astronominiais momentais.</p></section>
   #{links([['saule/','Saulėtekis ir saulėlydis','Miestas, data, civilinė prieblanda ir dienos trukmė.'],['menulio-fazes/','Mėnulio fazės','Tikros fazių akimirkos Lietuvos laiku.'],['menulio-kalendorius/2027/','2027 metų Mėnulio kalendorius','Metų mėnesių lentelės.']])}
  HTML
  page('astronominis-kalendorius','Astronominis kalendorius: Saulė ir Mėnulis',
    'Lygiadienių ir saulėgrįžų momentai Lietuvos laiku, penkių miestų saulėtekio skaičiuoklė ir 2027–2029 m. Mėnulio fazių lentelės.',seasons,'sun')

  printable_routes=[
   ['savaitiniai-planuokliai','Savaitinis planuoklis spausdinimui','Savaitės lapai su vieta prioritetams, dienų užduotims ir pastaboms.','Atsisiųskite savaitinį planuoklį PDF arba WebP formatu. A4 šablone rasite vietos savaitės prioritetams, dienų užduotims ir pastaboms.','week'],
   ['dienos-planuoklis','Dienos planuoklis spausdinimui','Nedatuotas dienos lapas laikui, svarbiausiems darbams ir užrašams.','Atsisiųskite nedatuotą dienos planuoklį PDF arba WebP formatu. A4 lape galėsite susidėlioti dienos laiką, svarbiausius darbus ir pastabas.','day'],
   ['seimos-kalendorius','Šeimos savaitės planuoklis','Atskiros skiltys šeimos narių planams ir bendroms savaitės veikloms.','Atsisiųskite šeimos savaitės planuoklį PDF arba WebP formatu. A4 šablone rasite atskiras skiltis šeimos narių planams ir bendroms veikloms.','family'],
   ['pamoku-tvarkarascio-sablonai','Pamokų tvarkaraščio šablonai','Tušti savaitės tvarkaraščiai rašymui ranka ir mokyklos užduotims.','Atsisiųskite spausdinamą pamokų tvarkaraštį PDF arba WebP formatu. Nedatuoti A4 savaitės šablonai skirti pamokoms ir mokyklos užduotims.','school'],
   ['darbo-grafiko-sablonai','Darbo grafiko šablonai','Nedatuoti darbo ir pamainų lapai. Atspausdinkite ir pildykite ranka.','Atsisiųskite nedatuotą darbo ir pamainų grafiko šabloną PDF arba WebP formatu. Pasirinkite juodai baltą arba spalvotą A4 planuoklį.','shift']
  ]
  printable_routes.each do |slug,title,copy,description,category|
   items=Pages::MANIFEST.select { |e|e['kind']=='blank' && e['category']==category }
   digital={
    'week'=>['/#calendar','Planuoti savaitę skaitmeniniame kalendoriuje'],
    'day'=>['/#day-details','Dienos įvykiai, užrašai ir užduotys'],
    'family'=>['/#calendar','Bendras šeimos įvykių kalendorius'],
    'school'=>['/pamoku-tvarkarastis/','Kurti skaitmeninį pamokų tvarkaraštį'],
    'shift'=>['/pamainu-grafikas/','Apskaičiuoti pamainų grafiką']
   }.fetch(category)
   body=Pages.intro(title,copy+' Nespalvotas ir spalvotas variantas paruoštas spausdinti A4 lape.')+"<section class=\"panel\"><h2>Pasirinkite spausdinamą variantą</h2><p>PDF yra vektorinis, o WebP sukurtas iš to paties PDF 600 PPI raiška. Peržiūros paveikslėlis yra tik miniatiūra. Spausdindami pasirinkite A4 lapą, tinkamą orientaciją ir 100 % dydį.</p></section>"+(items.empty? ? '<p>Šio rinkinio failai dar neparengti.</p>' : Pages.gallery(items,true))+"<p><a href=\"/tuscias-kalendorius/\">Peržiūrėti visus tuščius kalendorius</a> · <a href=\"#{digital[0]}\">#{digital[1]}</a></p>"
   page(slug,title+' – PDF ir WebP',description,body)
  end
 end
